// iOS only shows a launch image that matches the device exactly.
// Images are generated by scripts/generate-pwa-assets.mjs, which must list the same pixel sizes.
const DEVICES: Array<[width: number, height: number, ratio: number]> = [
  [375, 667, 2],
  [414, 896, 2],
  [375, 812, 3],
  [390, 844, 3],
  [393, 852, 3],
  [402, 874, 3],
  [414, 896, 3],
  [428, 926, 3],
  [430, 932, 3],
  [440, 956, 3],
]

export const IOS_SPLASH_IMAGES = DEVICES.map(([width, height, ratio]) => ({
  url: `/splash/${width * ratio}x${height * ratio}.png`,
  media: `(device-width: ${width}px) and (device-height: ${height}px) and (-webkit-device-pixel-ratio: ${ratio}) and (orientation: portrait)`,
}))
